90	TEST_F(XdsOverrideHostTest, NoConfigReportsError) {
91	  EXPECT_EQ(
92	      ApplyUpdate(BuildUpdate({"ipv4:127.0.0.1:441", "ipv4:127.0.0.1:442"}),
93	                  policy_.get()),
94	      absl::InvalidArgumentError("Missing policy config"));
95	}
