215	  class SubchannelState : public RefCounted<SubchannelState> {
216	   public:
217	    struct Bucket {
218	      std::atomic<uint64_t> successes;
219	      std::atomic<uint64_t> failures;
220	    };
221	
222	    void RotateBucket() {
223	      backup_bucket_->successes = 0;
224	      backup_bucket_->failures = 0;
225	      current_bucket_.swap(backup_bucket_);
226	      active_bucket_.store(current_bucket_.get());
227	    }
228	
229	    absl::optional<std::pair<double, uint64_t>> GetSuccessRateAndVolume() {
230	      uint64_t total_request =
231	          backup_bucket_->successes + backup_bucket_->failures;
232	      if (total_request == 0) {
233	        return absl::nullopt;
234	      }
235	      double success_rate =
236	          backup_bucket_->successes * 100.0 /
237	          (backup_bucket_->successes + backup_bucket_->failures);
238	      return {
239	          {success_rate, backup_bucket_->successes + backup_bucket_->failures}};
240	    }
241	
242	    void AddSubchannel(SubchannelWrapper* wrapper) {
243	      subchannels_.insert(wrapper);
244	    }
245	
246	    void RemoveSubchannel(SubchannelWrapper* wrapper) {
247	      subchannels_.erase(wrapper);
248	    }
249	
250	    void AddSuccessCount() { active_bucket_.load()->successes.fetch_add(1); }
251	
252	    void AddFailureCount() { active_bucket_.load()->failures.fetch_add(1); }
253	
254	    absl::optional<Timestamp> ejection_time() const { return ejection_time_; }
255	
256	    void Eject(const Timestamp& time) {
257	      ejection_time_ = time;
258	      ++multiplier_;
259	      for (auto& subchannel : subchannels_) {
260	        subchannel->Eject();
261	      }
262	    }
263	
264	    void Uneject() {
265	      ejection_time_.reset();
266	      for (auto& subchannel : subchannels_) {
267	        subchannel->Uneject();
268	      }
269	    }
270	
271	    bool MaybeUneject(uint64_t base_ejection_time_in_millis,
272	                      uint64_t max_ejection_time_in_millis) {
273	      if (!ejection_time_.has_value()) {
274	        if (multiplier_ > 0) {
275	          --multiplier_;
276	        }
277	      } else {
278	        GPR_ASSERT(ejection_time_.has_value());
279	        auto change_time = ejection_time_.value() +
280	                           Duration::Milliseconds(std::min(
281	                               base_ejection_time_in_millis * multiplier_,
282	                               std::max(base_ejection_time_in_millis,
283	                                        max_ejection_time_in_millis)));
284	        if (change_time < Timestamp::Now()) {
285	          Uneject();
286	          return true;
287	        }
288	      }
289	      return false;
290	    }
291	
292	    void DisableEjection() {
293	      Uneject();
294	      multiplier_ = 0;
295	    }
296	
297	   private:
298	    std::unique_ptr<Bucket> current_bucket_ = std::make_unique<Bucket>();
299	    std::unique_ptr<Bucket> backup_bucket_ = std::make_unique<Bucket>();
300	    // The bucket used to update call counts.
301	    // Points to either current_bucket or active_bucket.
302	    std::atomic<Bucket*> active_bucket_{current_bucket_.get()};
303	    uint32_t multiplier_ = 0;
304	    absl::optional<Timestamp> ejection_time_;
305	    std::set<SubchannelWrapper*> subchannels_;
306	  };
